#!/bin/sh
security_report(){ out="$REPORT_DIR/security-$(date +%Y%m%d-%H%M%S).txt"; { echo '== Identity =='; id; echo '== World writable =='; find /etc /usr/local "$CURRENT_HOME" -xdev -type f -perm -0002 -print 2>/dev/null; echo '== SUID/SGID =='; find /bin /sbin /usr -xdev -type f \( -perm -4000 -o -perm -2000 \) -print 2>/dev/null; echo '== SSH permissions =='; ls -ld "$CURRENT_HOME/.ssh" "$CURRENT_HOME/.ssh"/* 2>/dev/null; echo '== Accounts without passwords =='; awk -F: '($2==""){print $1}' /etc/shadow 2>/dev/null; } >"$out"; ui_text Security "$(cat "$out")\n\nSaved: $out"; }
security_tools_menu(){ while :; do c=$(ui_menu 'Security and permissions' 'Portable user-space security checks.' audit 'Run security audit' ssh 'Repair SSH permissions' home 'Repair home ownership' umask 'Configure default umask' suid 'List SUID and SGID files' writable 'List world-writable files' passwd 'Password and account tools' sudo 'Validate sudo/doas' integrity 'Configuration checksums' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in audit) security_report;; ssh) mkdir -p "$CURRENT_HOME/.ssh"; chmod 700 "$CURRENT_HOME/.ssh"; chmod 600 "$CURRENT_HOME/.ssh"/* 2>/dev/null || true;; home) need_root && as_root chown -R "$CURRENT_USER:$(id -gn "$CURRENT_USER" 2>/dev/null || echo "$CURRENT_USER")" "$CURRENT_HOME";; umask) v=$(ui_input umask 'Umask' 022) || continue; replace_block "$CURRENT_HOME/.profile" umask "umask $v";; suid) run_capture SUID find /bin /sbin /usr -xdev -type f \( -perm -4000 -o -perm -2000 \) -print;; writable) run_capture Writable find /etc /usr/local "$CURRENT_HOME" -xdev -type f -perm -0002 -print;; passwd) u=$(ui_input Password 'User' "$CURRENT_USER") || continue; as_root passwd "$u";; sudo) run_capture Privilege sh -c 'visudo -c 2>&1 || true; doas -C /etc/doas.conf 2>&1 || true';; integrity) find /etc -type f -maxdepth 3 -exec sha256sum {} + >"$REPORT_DIR/etc-checksums.txt" 2>/dev/null; ui_msg Integrity "Saved $REPORT_DIR/etc-checksums.txt";; back) return;; esac; done; }
